    TestCase.assertSame(sampleContext, fm.getContext());
    TestCase.assertFalse(fm.isRegistered());
    TestCase.assertEquals(0, this.httpService.getFilters().size());
    fm.setContext(null);
    TestCase.assertNull(fm.getContext());
    TestCase.assertFalse(fm.isRegistered());
    TestCase.assertEquals(0, this.httpService.getFilters().size());
}

